import{_ as o,o as e,c as s,a2 as t}from"./chunks/framework.CiKk3sJz.js";const x=JSON.parse('{"title":"漫画 · 第 7 话 阴影：界面的海拔系统","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.07-shadows.md","filePath":"comics/css/EP.07-shadows.md","lastUpdated":1792579602000}'),d={name:"comics/css/EP.07-shadows.md"};function r(h,a,l,i,c,n){return e(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-7-话-阴影-界面的海拔系统" tabindex="-1">漫画 · 第 7 话 阴影：界面的海拔系统 <a class="header-anchor" href="#漫画-·-第-7-话-阴影-界面的海拔系统" aria-label="Permalink to &quot;漫画 · 第 7 话 阴影：界面的海拔系统&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/07-shadows">docs/css/07-shadows.md</a> ｜ 原画：<a href="./EP.07-shadows.svg">EP.07-shadows.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。给聊天气泡加了 box-shadow，尾巴尖角处的阴影却&quot;断&quot;了，当场困惑。</li><li><strong>标签君</strong>：HTML5 结构师，摆出阴影三兄弟的分工表：矩形轮廓、字形轮廓、alpha 剪影各管一摊。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>阴影是界面&quot;海拔&quot;的语言。像素酱先弄懂三种阴影的轮廓差异，再学会&quot;接触 + 主体 + 环境&quot;三段式海拔写法，最后掌握性能红线：动画别直接改 box-shadow 值，抬升交给 transform、明暗交给伪元素 opacity，让阴影只在合成阶段动。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>box-shadow 沿<strong>盒子边框盒的矩形轮廓</strong>投射。气泡的三角尾巴是 <code>::after</code> 画在盒子外面的，阴影到矩形边缘就停了——尖角处&quot;漏光&quot;。透明 PNG、SVG 图标、clip-path 裁剪的异形同理，要贴合真实轮廓得用 <code>filter: drop-shadow()</code>，它基于元素渲染后的 <strong>alpha 通道</strong>投影，镂空处无阴影、真剪影。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三兄弟分工：<code>box-shadow</code> 贴矩形（唯一支持 spread 与 inset）；<code>text-shadow</code> 贴字形（无 spread/inset，可叠多层做霓虹）；<code>drop-shadow</code> 贴实际 alpha 轮廓（无 spread，小图标随便用）。多层阴影<strong>从上到下绘制、先写的在上层</strong>，所以&quot;细的写前面、粗的写后面&quot;，顺序反了视觉发闷。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>海拔三段式：<code>0 1px 2px</code> 接触细线 + <code>0 4px 12px</code> 主体 + <code>0 16px 40px</code> 大而淡的环境阴影。hover 抬升的正确姿势是 <code>transform: translateY(-4px)</code> 走合成器，深浅变化用伪元素 opacity 过渡——改 box-shadow 值必然触发逐帧重绘，是低端机掉帧的元凶。<code>will-change</code> 只给动画容器用，成片滥用会合成层爆炸。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li>三种阴影三种轮廓：box-shadow 矩形、text-shadow 字形、drop-shadow 实际 alpha 剪影。</li><li>多层阴影先细后粗（先写的在上层）；透明度控制在 6%~14% 不发脏。</li><li>动画别直接改 box-shadow 值——必重绘；抬升用 transform，明暗用伪元素 opacity。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：hover 想让卡片&quot;浮起&quot;，为什么不推荐 <code>transition: box-shadow</code>？正确做法是什么？</p><p><strong>答</strong>：box-shadow 值变化必然触发绘制（paint），逐帧重绘在低端机上直接掉帧。正确做法：位移用 <code>transform: translateY(-4px)</code>（合成器接管），阴影深浅变化交给承载阴影的伪元素做 <code>opacity</code> 过渡；<code>will-change: transform</code> 只加在列表容器上，防止合成层爆炸。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>box-shadow 全参数交互实验台：<a href="./../../examples/css/07-shadows/index-01-box-shadow-basics.html">examples/css/07-shadows/</a></li><li>多层阴影材质感：新拟态控件：<a href="./../../examples/css/07-shadows/index-02-neumorphism.html">index-02-neumorphism.html</a></li><li>text-shadow：霓虹字、浮雕、长投影：<a href="./../../examples/css/07-shadows/index-03-text-shadow.html">index-03-text-shadow.html</a></li><li>drop-shadow 与 box-shadow 的本质区别：<a href="./../../examples/css/07-shadows/index-04-drop-shadow.html">index-04-drop-shadow.html</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 8 话《渐变》——不是背景图，而是一门参数化的矢量绘图语言。</p>',22)])])}const u=o(d,[["render",r]]);export{x as __pageData,u as default};
